// Generate the self-contained report after verify-50000-20261006.mjs succeeds.
import fs from 'node:fs';
import assert from 'node:assert/strict';
const prefix='docs/rtp-50000-20261006';
const report=JSON.parse(fs.readFileSync(prefix+'.json'));
assert.equal(report.replay.matched,6000);
const pct=n=>(n*100).toFixed(1)+'%';
const num=n=>Math.round(n).toLocaleString('ja-JP');
const signed=n=>(n>0?'+':'')+num(n);
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const settings=report.settings;
const rows=settings.map(s=>`<tr><th scope="row">設定${s.setting}</th><td class="rtp">${(s.stopped.rtp*100).toFixed(2)}%</td><td class="muted">${s.stopped.rtpCi95.map(x=>(x*100).toFixed(2)).join('〜')}%</td><td>${pct(s.stopped.winRate)}</td><td>${pct(s.reach)}</td><td class="${s.stopped.meanNet>=0?'positive':'negative'}">${signed(s.stopped.meanNet)}</td><td>${signed(s.stopped.median)}</td><td>${num(s.meanGames)}</td></tr>`).join('');
const bins=settings[0].distribution.map((b,i)=>`<tr><th scope="row">${b.label}</th>${settings.map(s=>`<td>${pct(s.distribution[i].rate)}</td>`).join('')}</tr>`).join('');
const thresholds=settings[0].thresholds.map((b,i)=>`<tr><th scope="row">＋${num(b.pt)}pt</th>${settings.map(s=>`<td>${pct(s.thresholds[i].rate)}</td>`).join('')}</tr>`).join('');
const cols=settings.map(s=>`<th>設定${s.setting}</th>`).join('');
const html=`<!doctype html>
<html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>NOVA｜5万G試算 2026.10.06</title>
<style>
:root{color-scheme:light;--ink:#182941;--muted:#61718a;--line:#dbe3eb;--teal:#007f81;--pink:#b13e6a;--paper:#f3f6fa}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:system-ui,-apple-system,"Segoe UI","Yu Gothic",sans-serif;font-size:14px;line-height:1.7}main{max-width:1200px;margin:auto;padding:40px 26px 65px}header{padding:16px 0 27px;border-bottom:2px solid var(--ink)}.eyebrow{color:var(--teal);font-weight:800;letter-spacing:.13em;font-size:12px}h1{font-size:clamp(28px,4vw,44px);line-height:1.3;margin:10px 0}h2{font-size:22px;margin:0 0 6px}h3{font-size:16px;margin:0 0 8px}p{margin:7px 0}a{color:#006a9b}section{background:white;border:1px solid var(--line);border-radius:16px;padding:24px;margin-top:22px}.muted,small{color:var(--muted)}.lead{font-size:16px}.badges{display:flex;gap:9px;flex-wrap:wrap;margin-top:18px}.badge{background:#e3f1f0;padding:5px 12px;border-radius:6px;font-size:12px;font-weight:700}.notice{border-left:4px solid #bc8123;background:#fff6e5;padding:13px 17px;margin-top:20px;border-radius:0 8px 8px 0}.scroll{overflow-x:auto;margin-top:18px}table{width:100%;border-collapse:collapse;white-space:nowrap;font-variant-numeric:tabular-nums;font-size:13px}th,td{text-align:right;padding:12px 14px;border-bottom:1px solid var(--line)}th:first-child,td:first-child{text-align:left}thead th{font-size:11px;color:var(--muted);background:#f7f9fc}tbody th{font-weight:750}.rtp{font-weight:800;font-size:17px}.positive{color:var(--teal)}.negative{color:var(--pink)}.buttons{display:flex;flex-wrap:wrap;gap:8px;margin:18px 0}button{cursor:pointer;border:1px solid var(--line);background:white;border-radius:8px;color:var(--ink);padding:8px 19px;font:inherit;font-weight:700}button[aria-pressed=true]{background:var(--ink);color:white;border-color:var(--ink)}button:focus-visible{outline:3px solid #0cb9bc;outline-offset:3px}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:12px}.card{padding:15px;border-radius:10px;background:#f3f7fa}.card strong{display:block;font-size:23px;line-height:1.4}.card span{color:var(--muted);font-size:12px}.chartbox{overflow-x:auto}.chartbox svg{min-width:780px;width:100%;height:auto;display:block}.chart-note{font-size:12px}.legend{display:flex;gap:18px;flex-wrap:wrap}.dot{display:inline-block;width:10px;height:10px;border-radius:3px;margin-right:5px}.twocol{display:grid;grid-template-columns:1fr 1fr;gap:24px}.definition{display:grid;grid-template-columns:100px 1fr;gap:9px 20px}.definition dt{font-weight:750}.definition dd{margin:0;color:var(--muted)}details{margin-top:17px}summary{cursor:pointer;font-weight:700;padding:8px 0}footer{margin-top:22px;color:var(--muted);font-size:12px}code{font-size:12px;background:#edf1f6;padding:3px 5px;border-radius:4px;overflow-wrap:anywhere}.compact td,.compact th{padding:7px 12px}@media(max-width:650px){main{padding:20px 14px 36px}section{padding:18px 14px}.cards{grid-template-columns:1fr 1fr}.twocol{grid-template-columns:1fr}.definition{grid-template-columns:1fr;gap:3px}.definition dd{margin-bottom:10px}h2{font-size:20px}}@media print{body{background:white}main{padding:0}section{break-inside:avoid}.buttons,footer a{display:none}.scroll{overflow:visible}}
</style></head><body><main>
<header><div class="eyebrow">NOVA / SIMULATION REPORT / 2026.10.06</div><h1>5万Gで見る、設定別の出玉</h1><p class="lead">承認された調整を反映。各設定1,000回の試算を、反映後のコードで全件再現しました。</p><div class="badges"><span class="badge">最大50,000G × 6設定 × 1,000回</span><span class="badge">累計差枚＋10,000ptで停止</span><span class="badge">残りATpt＝手取り管理</span></div></header>
<div class="notice"><strong>機械割は目標付近。万pt到達率は高めです。</strong><br>設定5は${pct(settings[4].reach)}、設定6は${pct(settings[5].reach)}が5万G以内に累計差枚＋10,000ptへ到達。以前の「設定5＝約10%、設定6＝17〜19%」を満たす調整ではありません。</div>
<section><h2>全設定の結果</h2><p class="muted">全設定共通の上限が5万Gです。コンプリートした試行はその時点で終了するため、平均実回転数は短くなります。</p><div class="scroll"><table><thead><tr><th>設定</th><th>機械割</th><th>機械割の95%区間</th><th>勝率</th><th>＋1万pt到達率</th><th>平均差枚pt</th><th>中央値pt</th><th>平均実G数</th></tr></thead><tbody>${rows}</tbody></table></div><p class="muted chart-note">目標：設定1＝94〜95%、2＝96〜97%、3＝98〜99%、4＝100〜101%、5＝105〜106%、6＝約114%。設定5の生値は106.005%（約106.0%）。区間は試行のばらつきの目安で、モデル自体の誤差は含みません。</p></section>
<section><h2>最終差枚の分布</h2><p class="muted">遊技終了時の差枚を1,000pt刻みで集計。途中の到達率とは異なります。</p><div class="buttons" role="group" aria-label="分布の設定選択">${settings.map(s=>`<button type="button" data-setting="${s.setting}" aria-pressed="${s.setting===1}">設定${s.setting}</button>`).join('')}</div><div id="selected" aria-live="polite"></div><div class="chartbox" id="chart"></div><p class="legend chart-note"><span><i class="dot" style="background:#c76784"></i>マイナス</span><span><i class="dot" style="background:#209995"></i>0〜＋9,999pt</span><span><i class="dot" style="background:#be892f"></i>＋10,000pt以上</span></p><p class="muted chart-note">右端はコンプリート停止により集まる山です。停止がなかった場合の分布を表していません。棒に触れると件数を確認できます。</p><details><summary>全設定の分布表を見る（1,000pt刻み）</summary><div class="scroll"><table class="compact"><thead><tr><th>最終差枚pt</th>${cols}</tr></thead><tbody>${bins}</tbody></table></div></details></section>
<section><h2>プラス差枚への到達率</h2><p class="muted">5万G以内に一度でも到達した割合。到達後に下がった試行も含みます。＋10,000ptでは遊技停止。</p><div class="scroll"><table class="compact"><thead><tr><th>累計差枚</th>${cols}</tr></thead><tbody>${thresholds}</tbody></table></div></section>
<section><h2>今回反映した内容</h2><div class="twocol"><div><h3>AT中の特化当選率</h3><p>スイカ・弱ノヴァ成立時の追加特化抽選を、通常時30% → <strong>15%</strong>、AT高確中50% → <strong>25%</strong>へ。通常AT・上位ATとも共通です。</p><p class="muted">初期ptの全設定共通抽選、強ノヴァ60%抽選、特化ゾーン内の上乗せ性能は維持。</p></div><div><h3>CZ初当たり</h3><p>通常時のスイカ・弱ノヴァによるCZ抽選係数を調整。直前仕様に対する倍率は設定順に<strong>0.560 / 0.701 / 0.645 / 0.810 / 0.780 / 0.810</strong>です。</p><p class="muted">この倍率そのものがCZ当選確率ではありません。強ノヴァのCZ確定は維持。</p></div></div></section>
<section><h2>計算条件と読み方</h2><dl class="definition">${Object.entries({機械割:report.definitions.rtp,勝率:report.definitions.win,万pt到達率:report.definitions.reach,終了条件:report.definitions.stop,ゲーム数:report.definitions.games,開始条件:report.definitions.initial,検証方法:report.definitions.selection}).map(([k,v])=>`<dt>${k}</dt><dd>${esc(v)}</dd>`).join('')}</dl><p class="muted">実行した総ゲーム数：<strong>${num(report.totalActualGames)}G</strong>。各設定1,000シード、計6,000試行のBET・払い出し・最終差枚・最大差枚・状態別ゲーム数などが承認時の結果と完全一致しています。</p><details><summary>再計算・データ</summary><p><a href="rtp-50000-20261006.json">集計JSON</a> ／ <a href="rtp-50000-20261006-rows.json.gz" download>各試行の元データ（gzip JSON）</a></p><p>リポジトリのルートで <code>node scripts/verify-50000-20261006.mjs</code> を実行し、その後 <code>node scripts/report-50000-20261006.mjs</code> でこのページを再生成できます。ゲームの設定値は変更しません。</p><p class="muted">既存の減算区間を含む現行仕様での試算です。個別試行の結果や将来の実走値を保証するものではありません。</p></details></section>
<footer>計測モデル：${esc(report.version)} ／ 計測値は表示桁で四捨五入。<br>作成日時：${new Date(report.createdAt).toLocaleString('ja-JP',{timeZone:'Asia/Tokyo'})} JST</footer>
</main><script>
const data=${JSON.stringify(settings).replaceAll('<','\\u003c')};
const fmt=n=>Math.round(n).toLocaleString('ja-JP');
const sign=n=>(n>0?'+':'')+fmt(n);
function draw(setting){
 const s=data[setting-1],values=s.distribution,max=Math.max(.1,...values.map(b=>b.rate)),top=Math.ceil(max*10)/10;
 document.querySelectorAll('[data-setting]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.setting)===setting)));
 document.getElementById('selected').innerHTML='<div class="cards"><div class="card"><span>設定'+setting+'の勝率</span><strong>'+(100*s.stopped.winRate).toFixed(1)+'%</strong></div><div class="card"><span>差枚の中央値</span><strong>'+sign(s.stopped.median)+'pt</strong></div><div class="card"><span>下位10%の境目</span><strong>'+sign(s.stopped.p10)+'pt</strong></div><div class="card"><span>上位10%の境目</span><strong>'+sign(s.stopped.p90)+'pt</strong></div></div>';
 const W=1100,H=330,L=48,R=18,T=18,B=55,cw=W-L-R,step=cw/values.length,ch=H-T-B;
 let svg='<svg viewBox="0 0 '+W+' '+H+'" role="img" aria-label="設定'+setting+'の最終差枚分布">';
 for(let i=0;i<=4;i++){const y=T+ch-i*ch/4;svg+='<line x1="'+L+'" y1="'+y+'" x2="'+(W-R)+'" y2="'+y+'" stroke="#e4eaf0"/><text x="'+(L-8)+'" y="'+(y+4)+'" text-anchor="end" fill="#61718a" font-size="11">'+(top*100*i/4).toFixed(0)+'%</text>';}
 values.forEach((b,i)=>{const x=L+i*step+2,h=b.rate/top*ch,y=T+ch-h,color=b.upper!==null&&b.upper<=0?'#c76784':b.lower===10000?'#be892f':'#209995';svg+='<rect x="'+x+'" y="'+y+'" width="'+(step-4)+'" height="'+h+'" rx="2" fill="'+color+'"><title>'+b.label+'pt: '+(100*b.rate).toFixed(1)+'% ('+b.count+'件)</title></rect>';if(i===0||i===values.length-1||b.lower%5000===0){const label=i===0?'−20k未満':b.lower===10000?'＋10k以上':b.lower/1000+'k';svg+='<text x="'+(x+(step-4)/2)+'" y="'+(T+ch+22)+'" text-anchor="middle" fill="#61718a" font-size="11">'+label+'</text>';}});
 svg+='<text x="'+(W/2)+'" y="'+(H-5)+'" text-anchor="middle" fill="#61718a" font-size="12">最終差枚pt（1k＝1,000pt）</text></svg>';
 document.getElementById('chart').innerHTML=svg;
}
document.querySelectorAll('[data-setting]').forEach(b=>b.addEventListener('click',()=>draw(Number(b.dataset.setting))));draw(1);
</script></body></html>`;
fs.writeFileSync(prefix+'.html',html);
console.log('Created '+prefix+'.html');
